static bool ls_rt_unicode_in_ranges(const struct ls_rt_codepoint_range* ranges,
                                    size_t count, uint32_t scalar) {
    size_t low = 0;
    size_t high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (ranges[middle].last < scalar) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return low < count && ranges[low].first <= scalar && scalar <= ranges[low].last;
}

static const struct ls_rt_case_entry* ls_rt_unicode_find_case(
    const struct ls_rt_case_entry* entries, size_t count, uint32_t scalar) {
    size_t low = 0;
    size_t high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (entries[middle].ch < scalar) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if (low < count && entries[low].ch == scalar) {
        return &entries[low];
    }
    return NULL;
}

size_t ls_rt_unicode_upper(uint32_t scalar, uint32_t out[4]) {
    const struct ls_rt_case_entry* entry = ls_rt_unicode_find_case(
        ls_rt_unicode_upper_map,
        sizeof(ls_rt_unicode_upper_map) / sizeof(ls_rt_unicode_upper_map[0]),
        scalar);
    size_t index;
    if (entry == NULL) {
        out[0] = scalar;
        return 1;
    }
    for (index = 0; index < (size_t)entry->length; index += 1) {
        out[index] = ls_rt_unicode_upper_data[entry->offset + index];
    }
    return (size_t)entry->length;
}

size_t ls_rt_unicode_lower(uint32_t scalar, uint32_t out[4]) {
    const struct ls_rt_case_entry* entry = ls_rt_unicode_find_case(
        ls_rt_unicode_lower_map,
        sizeof(ls_rt_unicode_lower_map) / sizeof(ls_rt_unicode_lower_map[0]),
        scalar);
    size_t index;
    if (entry == NULL) {
        out[0] = scalar;
        return 1;
    }
    for (index = 0; index < (size_t)entry->length; index += 1) {
        out[index] = ls_rt_unicode_lower_data[entry->offset + index];
    }
    return (size_t)entry->length;
}

bool ls_rt_unicode_is_whitespace(uint32_t scalar) {
    return ls_rt_unicode_in_ranges(
        ls_rt_unicode_white_space,
        sizeof(ls_rt_unicode_white_space) / sizeof(ls_rt_unicode_white_space[0]),
        scalar);
}

bool ls_rt_unicode_char_is_printable(uint32_t scalar) {
    return !ls_rt_unicode_in_ranges(
        ls_rt_unicode_escape,
        sizeof(ls_rt_unicode_escape) / sizeof(ls_rt_unicode_escape[0]),
        scalar);
}

